//go:build amd64

package floats

// Abs, Neg, Square, Floor, Ceil, Trunc and RoundEven kernels (round.go),
// generated by go-asmgen (round_amd64_gen.go) into round_amd64.s. A kernel does
// the whole blocks of eight elements of a slice whose length is a positive
// multiple of eight; the Go code finishes the last seven with the scalar
// expression. The AVX2 kernels share the gate of the other AVX2 kernels
// (hasAVX2FMA, kernels_amd64.go); without AVX2+FMA Abs, Neg and Square run the
// SSE2 kernels (SSE2 is the amd64 baseline) and the rounding functions the
// scalar loop (SSE2 has no ROUNDPD). No kernel keeps a pointer: every stub is
// go:noescape.
//
//go:noescape
func absAVX2(dst, src []float64)

//go:noescape
func negAVX2(dst, src []float64)

//go:noescape
func squareAVX2(dst, src []float64)

//go:noescape
func floorAVX2(dst, src []float64)

//go:noescape
func ceilAVX2(dst, src []float64)

//go:noescape
func truncAVX2(dst, src []float64)

//go:noescape
func rintAVX2(dst, src []float64)

//go:noescape
func absSSE2(dst, src []float64)

//go:noescape
func negSSE2(dst, src []float64)

//go:noescape
func squareSSE2(dst, src []float64)

func vabs(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 {
		if hasAVX2FMA {
			absAVX2(dst[:n], src[:n])
		} else {
			absSSE2(dst[:n], src[:n])
		}
	}
	absRef(dst[n:], src[n:])
}

func vneg(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 {
		if hasAVX2FMA {
			negAVX2(dst[:n], src[:n])
		} else {
			negSSE2(dst[:n], src[:n])
		}
	}
	negRef(dst[n:], src[n:])
}

func vsquare(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 {
		if hasAVX2FMA {
			squareAVX2(dst[:n], src[:n])
		} else {
			squareSSE2(dst[:n], src[:n])
		}
	}
	squareRef(dst[n:], src[n:])
}

func vfloor(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 && hasAVX2FMA {
		floorAVX2(dst[:n], src[:n])
	} else {
		n = 0
	}
	floorRef(dst[n:], src[n:])
}

func vceil(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 && hasAVX2FMA {
		ceilAVX2(dst[:n], src[:n])
	} else {
		n = 0
	}
	ceilRef(dst[n:], src[n:])
}

func vtrunc(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 && hasAVX2FMA {
		truncAVX2(dst[:n], src[:n])
	} else {
		n = 0
	}
	truncRef(dst[n:], src[n:])
}

func vrint(dst, src []float64) {
	n := len(src) &^ 7
	if n > 0 && hasAVX2FMA {
		rintAVX2(dst[:n], src[:n])
	} else {
		n = 0
	}
	rintRef(dst[n:], src[n:])
}
